// Retained inputs accepted by actual KR00967 native consumers (CP274).
// These constants are not generated by the Rust projector under test.
use kr_wire::kr00967::{start121_duel, start121_roster};
fn hex(value: &str) -> Vec<u8> {
    value
        .as_bytes()
        .as_chunks::<2>()
        .0
        .iter()
        .map(|pair| u8::from_str_radix(std::str::from_utf8(pair).unwrap(), 16).unwrap())
        .collect()
}
const TWO: &str = "5a96ca53ff96ca368d96ca539596ca539596ca539596ca5395a6f3539597dc539596ca539eff9c2bd0f1ab3ff996fb63f096ca539596ca519596ca539596ca53959635539569ca53959635ac6a96ca539596ca539597cb539496ca529596ca536a6935ac9596ca536a96ca5395a5695a22a55aa56996ca539396ca528da5695a5a";
const FOUR: &str = "";
const EIGHT: &str = "";
#[test]
fn measured_accepted_rosters_project_back_to_independently_retained_native_inputs() {
    let two = hex(TWO);
    let four = hex(FOUR);
    let eight = hex(EIGHT);
    assert_eq!(start121_roster(&eight, &[0, 1, 0, 1]).unwrap(), four);
    assert_eq!(start121_roster(&eight, &[0, 1]).unwrap(), two);
    assert_eq!(start121_roster(&four, &[0, 1]).unwrap(), two);
    assert_eq!(start121_duel(&four).unwrap(), two);
    for (body, teams) in [
        (&two, vec![0, 1]),
        (&four, vec![0, 1, 0, 1]),
        (&eight, vec![0, 1, 0, 1, 0, 1, 0, 1]),
    ] {
        assert_eq!(start121_roster(body, &teams).unwrap(), *body);
    }
}
#[test]
fn unsupported_count_expansion_team_change_and_truncation_never_produce_a_start() {
    let two = hex(TWO);
    let four = hex(FOUR);
    let eight = hex(EIGHT);
    for count in [0, 1, 3, 5, 7, 9] {
        assert!(start121_roster(&eight, &vec![0; count]).is_err());
    }
    assert!(start121_roster(&two, &[0, 1, 0, 1]).is_err());
    assert!(start121_roster(&four, &[1, 0]).is_err());
    assert!(start121_roster(&four, &[0, 2]).is_err());
    for n in 0..eight.len() {
        assert!(start121_roster(&eight[..n], &[0, 1]).is_err());
    }
}

// This changes only the name/code in retained native inputs to exercise variable
// offsets. It is a synthetic codec regression, not native Factory07 evidence.
fn changed_name(body: &[u8], name: &[u8]) -> Vec<u8> {
    use kr_wire::kr00967::{decode_bytes, encode_bytes};
    use kr_wire::{Width, read_uint, write_uint};
    let size = read_uint(&body[1..5], Width::U32).unwrap() as usize;
    let stream = decode_bytes(&body[5..5 + size]).unwrap();
    let mut out_stream = stream[..26].to_vec();
    out_stream.extend(281_u16.to_le_bytes());
    out_stream.extend((name.len() as u32).to_le_bytes());
    out_stream.extend(name);
    out_stream.extend_from_slice(&stream[43..]);
    let stream_size = out_stream.len();
    out_stream[1..5].copy_from_slice(&((stream_size - 5) as u32).to_le_bytes());
    let mut out = body[..1].to_vec();
    out.extend(write_uint(stream_size as u64, Width::U32).unwrap());
    out.extend(encode_bytes(&out_stream).unwrap());
    out.extend_from_slice(&body[5 + size..]);
    out
}
#[test]
fn variable_map_name_preserves_independent_retained_rows_and_tail() {
    use kr_wire::kr00967::{StartPlayer, start121_map, start121_players, start121_teams};
    for name in [
        b"F".as_slice(),
        b"Factory07",
        b"LongerMapNameThanExVillage01",
    ] {
        let two = changed_name(&hex(TWO), name);
        let eight = changed_name(&hex(EIGHT), name);
        assert_eq!(start121_map(&two).unwrap(), (281, name.to_vec()));
        assert_eq!(start121_duel(&eight).unwrap(), two);
        assert_eq!(
            start121_teams(&eight, &[0, 1, 0, 1, 0, 1, 0, 1]).unwrap(),
            eight
        );
        let players = [
            StartPlayer {
                slot: 0,
                spawn: 0,
                character: 0,
                team: 0,
            },
            StartPlayer {
                slot: 1,
                spawn: 1,
                character: 1,
                team: 1,
            },
        ];
        assert_eq!(start121_players(&eight, &players).unwrap(), two);
        for n in 0..two.len() {
            assert!(start121_map(&two[..n]).is_err());
        }
    }
}
